function HomeOverview({name,currentDone,onTab,picks,liveMatches}:{name:string,currentDone:number,onTab:(tab:"inicio"|"quiniela"|"pronosticos"|"clasificacion"|"mas")=>void,picks:Record<string,string>,liveMatches:Record<string,{home_score:number,away_score:number,status:string}>}){
 const standings:Record<string,string>={"Derio A":"2º · 8 pts","Beasain":"15º · 4 pts","Derio B":"13º · 1 pto","Escolapios":"3º · 6 pts","Derio Fem":"13º · 1 pto","Lakua":"10º · 3 pts","Juvenil A":"7º · 3 pts","Iturrigorri A":"8º · 3 pts"};
 const fixtureTs=(g:{date?:string,time?:string})=>{if(!g.date)return Number.MAX_SAFE_INTEGER;const [d,m,y]=g.date.split("/").map(Number);const [h=23,min=59]=(g.time||"23:59").split(":").map(Number);return new Date(y,m-1,d,h,min).getTime()};
 const homeGames=weeklyTeams.map(team=>({name:team,...(quizFixtures[1][team]||{})})).sort((a,b)=>fixtureTs(a)-fixtureTs(b));
 const now=Date.now();
 const playable=homeGames.filter(g=>g.status!=="rest");
 const firstKickoff=playable.length?Math.min(...playable.map(fixtureTs)):Number.MAX_SAFE_INTEGER;
 const liveCount=playable.filter(g=>liveMatches[g.name]?.status==="live").length;
 const finalCount=playable.filter(g=>["final","finished"].includes(liveMatches[g.name]?.status)).length;
 const started=now>=firstKickoff||liveCount>0||finalCount>0;
 const finished=playable.length>0&&finalCount===playable.length;
 const provisionalHits=playable.reduce((n,g)=>{const db=liveMatches[g.name];if(!db||!["live","final","finished"].includes(db.status))return n;const actual=Number(db.home_score)===Number(db.away_score)?"X":Number(db.home_score)>Number(db.away_score)?"1":"2";return n+(picks["1:"+g.name]===actual?1:0)},0);
 const pendingCount=Math.max(0,playable.length-liveCount-finalCount);
 return <div className="qdHome">
  <aside className="qdSide">
   <div className="qdSideTitle">MENÚ</div>
   <button className="active" onClick={()=>onTab("inicio")}><HomeIcon/>Inicio</button>
   <button onClick={()=>onTab("quiniela")}><TargetIcon/>Quiniela</button>
   <button onClick={()=>onTab("pronosticos")}><UsersIcon/>Mis pronósticos</button>
   <button onClick={()=>onTab("clasificacion")}><StandingsIcon/>Clasificación</button>
   <button onClick={()=>onTab("mas")}><AccountIcon/>Mi cuenta</button>
   <div className="qdSeason"><small>TEMPORADA</small><b>2026/27</b></div>
  </aside>
  <div className="qdHomeMain">
   <section className="qdBanner">
    <img src={asset("branding/ImagenPortada.png?v=202609281638")} alt="QuiniDerio · CD Derio" loading="eager" decoding="sync" fetchPriority="high"/>
    <div className="qdBannerShade"/>
    <div className="qdBannerContent"><span><i/> TEMPORADA 2026/27</span><h1><span className="qd-quini">QUINI</span><span className="qd-de">DE</span><span className="qd-rio">RIO</span></h1><p>LA QUINIELA DEL CD DERIO</p></div>
   </section>
   {started&&<section className={"liveRoundHub "+(finished?"finished":"playing")}>
    <div className="liveRoundHero"><small>JORNADA 1</small><h2>{finished?"FINALIZADA":"EN JUEGO"}</h2><p>{finished?"Resultados y puntuación de la jornada":liveCount+" partidos en directo"}</p></div>
    <div className="liveRoundCounters"><span><b>{liveCount}</b>EN JUEGO</span><span><b>{finalCount}</b>FINALIZADOS</span><span><b>{pendingCount}</b>PENDIENTES</span><span><b>{provisionalHits}</b>PTS PROV.</span></div>
    <div className="liveRoundMatches">{playable.map(game=>{const db=liveMatches[game.name];const rival=game.opponent||"Por confirmar";const home=game.isHome===false?rival:game.name;const away=game.isHome===false?game.name:rival;const pick=picks["1:"+game.name]||"—";const actual=db?Number(db.home_score)===Number(db.away_score)?"X":Number(db.home_score)>Number(db.away_score)?"1":"2":"";const state=db&&["final","finished"].includes(db.status)?"FINAL":db?.status==="live"?"EN JUEGO":"PENDIENTE";return <button key={"live-"+game.name} type="button" onClick={()=>onTab("quiniela")} className={"liveRoundMatch "+state.toLowerCase().replace(" ","-")}><small>{game.competition||game.name}<em>{state}</em></small><div><span>{home}</span><strong>{db&&state!=="PENDIENTE"?db.home_score+" - "+db.away_score:"— : —"}</strong><span>{away}</span></div><footer><span>Mi pronóstico</span><b>{pick}</b></footer></button>})}</div>
   </section>}
   <section className="qdSummary">
    <button className="qdAction" onClick={()=>onTab("quiniela")}><small>HAZ TU PRONÓSTICO</small><b>Jornada 1</b><span>Completa los 6 partidos de la jornada.</span><em>Ir a mi quiniela</em></button>
    <article><small>ESTADO</small><b>{currentDone}/6</b><span>{currentDone===6?"Pronósticos completados":"Pronósticos realizados"}</span></article>
    <button onClick={()=>onTab("clasificacion")}><small>LÍDER ACTUAL</small><b>—</b><span>Clasificación general</span></button>
    <button onClick={()=>onTab("clasificacion")}><small>TU POSICIÓN</small><b>—</b><span>0 PTS</span></button>
   </section>
   <section className="qdRound">
    <div className="qdRoundHead"><div><h2>Jornada 1</h2><span>Temporada 2026/27</span></div><button onClick={()=>onTab("quiniela")}>Hacer quiniela</button></div>
    <div className="qdRoundTabs">{[1,2,3,4,5,6,7,8].map(n=><span className={n===1?"active":""} key={n}>J{n}</span>)}</div>
    <div className="qdFixtureList">{homeGames.map(game=>{const rival=game.opponent||"Por confirmar";const home=game.isHome===false?rival:game.name;const away=game.isHome===false?game.name:rival;return game.status==="rest"?<div className="qdFixture qdRest" key={game.name}><div className="qdClub home"><b>{game.name}</b><ClubCrest src="/api/assets/Escudos/cd_derio.png" name={game.name}/></div><div className="qdKick"><small>Jornada 1</small><strong>Descanso</strong></div><div className="qdClub qdRestLabel"><b>Sin partido</b></div></div>:<div className="qdFixture" key={game.name}><div className="qdClub home"><span className="qdClubName"><b>{home}</b>{standings[home]&&<small>{standings[home]}</small>}</span><ClubCrest src={game.isHome===false?game.crest||rivalCrests[game.name]:"/api/assets/Escudos/cd_derio.png"} name={home}/></div><div className="qdKick"><small>{game.date||"Fecha pendiente"}</small><strong>{game.time||"—"}</strong></div><div className="qdClub"><ClubCrest src={game.isHome===false?"/api/assets/Escudos/cd_derio.png":game.crest||rivalCrests[game.name]} name={away}/><span className="qdClubName"><b>{away}</b>{standings[away]&&<small>{standings[away]}</small>}</span></div></div>})}</div>
   </section>
  </div>
 </div>
}
function Brand({avatar,avatarUrl,name,onHome}:{avatar?:string,avatarUrl?:string,name?:string,onHome?:()=>void}){return <header className="brandBar glassHeader"><div className="brandMark"><img src="/api/assets/branding/LogoApp.png" alt="QuiniDerio"/><div><b className="logo"><span className="qd-quini">QUINI</span><span className="qd-de">DE</span><span className="qd-rio">RIO</span></b><small>LA QUINIELA DEL CD DERIO</small></div></div>{avatar&&<button type="button" className="avatar userChip" onClick={onHome} aria-label="Abrir Mi cuenta"><span>{avatarUrl?<img src={avatarUrl} alt="" className="headerAvatarImg"/>:avatar}</span>{name&&<b title={name}>{name}</b>}</button>}</header>}
function Choice({title,points,value,options,onChange,visual}:{title:string,points:string,value:string,options:string[],onChange:(v:string)=>void,visual?:"up"|"down"|"red"|"cards"}){return <section className={`choice visualChoice ${visual||""}`}><span className="choiceHead"><span className="choiceTitle">{visual&&<i className={`choiceVisual ${visual}`} aria-hidden="true">{visual==="up"?"↑":visual==="down"?"↓":visual==="red"?"":<><u></u><u></u></>}</i>}<b>{title}</b></span><em>{points}</em></span><div className="optionCards">{options.map(o=><button type="button" className={value===o?"active":""} onClick={()=>onChange(o)} key={o}><i>{o.split(" ").map(x=>x[0]).slice(0,2).join("")}</i><strong>{o}</strong></button>)}</div></section>}

